import{_ as a,I as i,c as n,o as s,a5 as l,J as o,w as c}from"./chunks/framework.Dl43PoGR.js";const b=JSON.parse('{"title":"Contingency Management Procedures","description":"","frontmatter":{"title":"Contingency Management Procedures","outline":"deep","prev":{"text":"Routines – Post-Session","link":"/trading-with-pav/routines-post-session"},"next":{"text":"Action Affirmation (AA) Statements","link":"/trading-with-pav/action-affirmation-aa-statements"}},"headers":[],"relativePath":"trading-with-pav/contingency-management-procedures.md","filePath":"trading-with-pav/contingency-management-procedures.md"}'),d={name:"trading-with-pav/contingency-management-procedures.md"};function h(m,e,f,p,u,g){const r=i("GraphComment"),t=i("ClientOnly");return s(),n("div",null,[e[0]||(e[0]=l('<h1 id="contingency-management-procedures" tabindex="-1">Contingency Management Procedures <a class="header-anchor" href="#contingency-management-procedures" aria-label="Permalink to “Contingency Management Procedures”">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#contingency-management-procedures-1">Contingency Management Procedures</a><ul><li><a href="#sources-of-threat-error">Sources of Threat &amp; Error:</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="contingency-management-procedures-1" tabindex="-1">Contingency Management Procedures <a class="header-anchor" href="#contingency-management-procedures-1" aria-label="Permalink to “Contingency Management Procedures”">​</a></h2><h3 id="sources-of-threat-error" tabindex="-1">Sources of Threat &amp; Error: <a class="header-anchor" href="#sources-of-threat-error" aria-label="Permalink to “Sources of Threat &amp; Error:”">​</a></h3><ol><li>Evidence of Illness, Stress or Negativity Impacting Trading Decisions</li><li>External Distraction</li><li>Incorrect Order Entry or Incorrect Fill</li><li>Loss of Connectivity (ISP, Computer, Platform) While in a Trade</li><li>Session or Business Drawdown Limits Hit</li><li>Violation of Rules</li></ol><h4 id="evidence-of-illness-stress-or-negativity-impacting-trading-decisions" tabindex="-1">Evidence of Illness, Stress or Negativity Impacting Trading Decisions <a class="header-anchor" href="#evidence-of-illness-stress-or-negativity-impacting-trading-decisions" aria-label="Permalink to “Evidence of Illness, Stress or Negativity Impacting Trading Decisions”">​</a></h4><ol><li>If I have live trades, immediately either: <ul><li>a) Close the trades and cancel any working orders; or</li><li>b) If positions are in profit, confirm appropriate stop (not &lt; breakeven) and target orders, and walk away.</li></ul></li><li>If I have working orders, cancel them.</li><li>Record details of the occurrence, for consideration during the post-session review.</li><li>Consider the need for a break, or a relaxation or recovery session, or for cancellation of the remainder of the session.</li></ol><h4 id="external-distraction-which-can-t-be-ignored" tabindex="-1">External Distraction (which can’t be ignored) <a class="header-anchor" href="#external-distraction-which-can-t-be-ignored" aria-label="Permalink to “External Distraction (which can’t be ignored)”">​</a></h4><ol><li>If I have live trades, immediately either: <ul><li>a) Close the trades and cancel any working orders; or</li><li>b) If positions are in profit, confirm appropriate stop (not &lt; breakeven) and target orders.</li></ul></li><li>If I have working orders, cancel them.</li><li>Deal with the distraction.</li><li>Record details of the occurrence, as soon as possible, for consideration during the post session review.</li><li>Consider the need for a break, or a relaxation or recover session prior to restart.</li></ol><h4 id="incorrect-order-entry-or-incorrect-fill" tabindex="-1">Incorrect Order Entry or Incorrect Fill <a class="header-anchor" href="#incorrect-order-entry-or-incorrect-fill" aria-label="Permalink to “Incorrect Order Entry or Incorrect Fill”">​</a></h4><ol><li>Immediately cancel the order if it hasn’t been filled.</li><li>If the order is filled, rapidly assess the situation. <ul><li>a) If analysis indicates potential for the market to move rapidly against the position, EXIT.</li><li>b) Else set an aggressive stop to minimize loss and manage the position to try to work a profitable exit.</li></ul></li><li>Record details of the error, for consideration during the post-session review.</li><li>Contact broker immediately if error is due to a broker-error (incorrect fill).</li><li>Consider the need for a break, or a relaxation or recovery session.</li></ol><h4 id="loss-of-connectivity-isp-computer-platform-while-in-a-trade" tabindex="-1">Loss of Connectivity (ISP, Computer, Platform) While in a Trade <a class="header-anchor" href="#loss-of-connectivity-isp-computer-platform-while-in-a-trade" aria-label="Permalink to “Loss of Connectivity (ISP, Computer, Platform) While in a Trade”">​</a></h4><ol><li>Close any open trades and pending orders via whichever of these means is available and quickest: <ul><li>a) Connecting to the platform via a backup computer/mobile.</li><li>b) Connect to the broker online via their web platform.</li><li>c) Immediately contact the broker via phone and/or live chat.</li></ul></li><li>Resolve the issue if possible and continue with the session.</li><li>If not continuing, conduct the post-session routine.</li></ol><div class="tip custom-block"><p class="custom-block-title"><strong>NOTE</strong>:</p><p>All orders placed into the platform should have an attached stop and target order.</p></div><h4 id="session-or-business-drawdown-limits-hit" tabindex="-1">Session or Business Drawdown Limits Hit <a class="header-anchor" href="#session-or-business-drawdown-limits-hit" aria-label="Permalink to “Session or Business Drawdown Limits Hit”">​</a></h4><ol><li>Immediately exit all trades.</li><li>Consider the need for a break, or a relaxation or recovery session.</li><li>Complete the Post-Session routine.</li></ol><h4 id="violation-of-rules" tabindex="-1">Violation of Rules <a class="header-anchor" href="#violation-of-rules" aria-label="Permalink to “Violation of Rules”">​</a></h4><ol><li>If I violate any part of my trading plan, I will do the following: <ul><li>a) Do not put on any new trades.</li><li>b) Close trades that should be closed.</li><li>c) Manage open trades until the exit.</li></ul></li><li>Record details of the violation, for consideration during the post-session review.</li><li>Consider the need for a break, or a relaxation or recovery session.</li></ol><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to “Comments”">​</a></h2>',19)),o(t,null,{default:c(()=>[o(r)]),_:1})])}const y=a(d,[["render",h]]);export{b as __pageData,y as default};
